def convert(source, target):
    """Convert ``source`` to ``target``; ``target`` is only replaced when all rows convert."""
    rows = 0
    target = Path(target)
    partial = target.with_name(target.name + ".partial")
    try:
        with open(source, newline="", encoding="utf-8") as supplier, \
                open(partial, "w", newline="", encoding="utf-8") as out:
            writer = csv.writer(out)
            writer.writerow(("sku", "price_cents"))
            reader = csv.DictReader(supplier, delimiter=";")
            for row in reader:
                if row["currency"].strip() != "EUR":
                    continue
                try:
                    cents = piece_cents(to_cents(row["price"]), row["pack"] or 1)
                except (ArithmeticError, ValueError, TypeError) as exc:
                    raise ValueError(
                        f"{source}, line {reader.line_num}: article {row['article']!r}: "
                        f"cannot read price {row['price']!r} / pack {row['pack']!r} "
                        f"({type(exc).__name__})"
                    ) from exc
                writer.writerow((row["article"].strip(), cents))
                rows += 1
                if rows % 10 == 0:
                    print(f"{rows} rows")
        os.replace(partial, target)
    finally:
        partial.unlink(missing_ok=True)
    return rows


def main(argv):
    if len(argv) != 3:
        print(__doc__, file=sys.stderr)
        return 2
    try:
        rows = convert(argv[1], argv[2])
    except (OSError, ValueError, KeyError) as exc:
        print(f"convert failed: {exc}", file=sys.stderr)
        return 1

